actions.script:
                // ZE-SALES-001 (SL-032/SL-046): reject non-numeric Quantity/Unit Price/Discount up front so a
                // typo like "wads" returns a friendly error instead of a BigDecimal NumberFormatException (which
                // would break the add and the GST math). Blank is allowed (price auto-fills; qty defaults to 0).
                def _numOk = { v -> !v || v.toString().trim() == '' || (v.toString().trim() ==~ /-?\d*\.?\d+/) }
                if (!_numOk(quantity) || !_numOk(amount) || !_numOk(discountPercent)) {
                    ec.message.addError("Quantity, Unit Price and Discount must be numbers (letters aren't allowed).")
                    return
                }
                // GST intra/inter-state is decided by the parties' registered state (tax-registration
                // regionGeoId) — the same source the invoice service uses. (Previously read stateProvinceGeoId
                // off PartyContactMechInfo, which has no such field, so it errored or always fell back to IGST.)
                // ZE-SALES-020 (SL-075): guard the lookup — partyId is REQUIRED on get#PartyTaxRegistration, so a
                // null buyer (a B2C / walk-in invoice with no customer party) fails its required-field validation,
                // and that error POISONS the rest of the transition (Moqui refuses to run every later service,
                // incl. create#InvoiceItem) -> "Add Item" silently adds nothing. Only call when the party is set;
                // the elvis chain below already null-tolerates a null registration.
                def _sReg = curInv.fromPartyId ? ec.service.sync().name("zenith.tax.TaxServices.get#PartyTaxRegistration").parameters([partyId:curInv.fromPartyId]).call() : null
                def _bReg = curInv.toPartyId ? ec.service.sync().name("zenith.tax.TaxServices.get#PartyTaxRegistration").parameters([partyId:curInv.toPartyId]).call() : null
                // ZE-SALES-019 (SL-041): the place of supply for THIS invoice is what's entered/displayed ON it
                // — the supplier/buyer GSTIN (state = first 2 digits) or the placeOfSupply code — NOT only the
                // party's saved registration (often absent for a customer, so a GSTIN-on-the-invoice inter-state
                // sale was wrongly taxed CGST+SGST). Prefer the invoice's own values, then the registration.
                def _st2 = { s -> (s && s.toString().trim().length() >= 2 && s.toString().trim().substring(0,2) ==~ /[0-9]{2}/) ? s.toString().trim().substring(0,2) : null }
                def _c2 = { s -> (s && s.toString().trim() ==~ /[0-9]{2}/) ? s.toString().trim() : null }
                def sellerState = _st2(curInv.supplierGstin) ?: _c2(curInv.supplierStateCode) ?: _c2(_sReg?.regionGeoId) ?: _st2(_sReg?.registrationNumber)
                def buyerState = _st2(curInv.buyerGstin) ?: _c2(curInv.placeOfSupplyStateCode) ?: _c2(_bReg?.regionGeoId) ?: _st2(_bReg?.registrationNumber)
                // Default to INTRA-state (CGST+SGST) when the buyer's state is unknown (e.g. a GSTIN-less
                // B2C customer): place of supply falls back to the seller's state. Only a KNOWN, different
                // buyer state is inter-state (IGST). This matches the tax engine (IndiaTaxServices) and
                // add#InvoiceItem, which previously disagreed with this screen's old IGST-by-default.
                def isInterstate = false
                if (sellerState && buyerState && sellerState != buyerState) {
                    isInterstate = true
                }

                def qty = new BigDecimal(quantity ?: 0)
                def price = new BigDecimal(amount ?: 0)
                // Sync price with Inventory and Pricing: auto-fill when the user leaves Unit Price blank
                if (price.signum() == 0 && productId) {
                    try {
                        def _pr = ec.service.sync().name("zenith.pricing.PricingServices.calculate#Price")
                                    .parameters([productId:productId, quantity:(qty.signum()>0?qty:1), organizationPartyId:curInv.fromPartyId, customerPartyId:curInv.toPartyId]).call()
                        if (_pr?.unitPrice != null && (_pr.unitPrice as BigDecimal).signum() == 1) price = _pr.unitPrice as BigDecimal
                    } catch (Exception e) { }
                    if (price.signum() == 0) {
                        def _p = ec.entity.find("mantle.product.Product").condition("productId", productId).one()
                        if (_p?.mrpAmount != null) price = _p.mrpAmount as BigDecimal
                    }
                }
                // ZE-SALES-020 (SL-042): line discount — GST is charged on the DISCOUNTED taxable value.
                def gross = qty.multiply(price)
                def discPct = new BigDecimal(discountPercent ?: 0)
                def discAmt = gross.multiply(discPct).divide(new BigDecimal(100), 2, java.math.RoundingMode.HALF_UP)
                def taxableVal = gross.subtract(discAmt)
                def taxPct = new BigDecimal(taxPercentage ?: 0)

                def igstRate = 0.0
                def cgstRate = 0.0
                def sgstRate = 0.0
                def igstAmount = 0.0
                def cgstAmount = 0.0
                def sgstAmount = 0.0

                if (taxPct > 0) {
                    if (isInterstate) {
                        igstRate = taxPct
                        igstAmount = taxableVal.multiply(taxPct).divide(new BigDecimal(100), 2, java.math.RoundingMode.HALF_UP)
                    } else {
                        cgstRate = taxPct.divide(new BigDecimal(2), 2, java.math.RoundingMode.HALF_UP)
                        sgstRate = cgstRate
                        cgstAmount = taxableVal.multiply(cgstRate).divide(new BigDecimal(100), 2, java.math.RoundingMode.HALF_UP)
                        sgstAmount = cgstAmount
                    }
                }
                // Reverse charge: the supplier collects no GST (the buyer self-assesses). Keep the rates for
                // the invoice's RCM declaration but zero the collected amounts.
                if (curInv.isReverseCharge == 'Y') {
                    igstAmount = 0.0; cgstAmount = 0.0; sgstAmount = 0.0
                }

                // ZE-SALES-002 (SL-032): the line-items grid shows the item description; when the user picks a
                // product but leaves the Description box blank it saved null and the grid read "N/A". Default the
                // description to the product's name so the grid shows the product, not N/A.
                def _prodForDesc = productId ? ec.entity.find("mantle.product.Product").condition("productId", productId).one() : null
                def _finalDesc = ((description ?: '').toString().trim()) ?: (_prodForDesc?.productName ?: '')

                // Call standard create item service but pass extended fields
                def inMap = context + [
                    description: _finalDesc,
                    itemTypeEnumId: 'ItemSales',
                    amount: price,
                    taxableAmount: taxableVal,
                    discountPercent: discPct, discountAmount: discAmt,
                    igstRate: igstRate, igstAmount: igstAmount,
                    cgstRate: cgstRate, cgstAmount: cgstAmount,
                    sgstRate: sgstRate, sgstAmount: sgstAmount
                ]
                ec.service.sync().name("create#mantle.account.invoice.InvoiceItem").parameters(inMap).call()

                // Refresh the header grand total (invoiceTotal/unpaidTotal) from the items.
                ec.service.sync().name("mantle.account.InvoiceServices.update#InvoiceTotals").parameters([invoiceId:invoiceId]).call()

                // Aggregate Indian GST totals onto the invoice header (custom fields).
                def invItems = ec.entity.find("mantle.account.invoice.InvoiceItem").condition("invoiceId", invoiceId).list()
                def tCgst = 0.0, tSgst = 0.0, tIgst = 0.0, tTaxable = 0.0
                for (def it : invItems) {
                    tCgst += (it.cgstAmount ?: 0.0)
                    tSgst += (it.sgstAmount ?: 0.0)
                    tIgst += (it.igstAmount ?: 0.0)
                    tTaxable += (it.taxableAmount ?: ((it.quantity?:1)*(it.amount?:0)))
                }
                // ZE-SALES-020 (SL-042): invoiceTotal is the pre-tax subtotal the print adds tax to; keep it =
                // the discounted taxable (update#InvoiceTotals sums gross line amounts, ignoring the discount).
                ec.service.sync().name("update#mantle.account.invoice.Invoice").parameters([
                    invoiceId: invoiceId,
                    invoiceTotal: tTaxable, unpaidTotal: tTaxable,
                    totalCgst: tCgst, totalSgst: tSgst, totalIgst: tIgst, totalTaxableAmount: tTaxable
                ]).call()

def rcm = (isReverseCharge == 'Y') ? 'Y' : 'N'
ec.service.sync().name("update#mantle.account.invoice.Invoice").parameters([invoiceId:invoiceId, isReverseCharge:rcm]).call()
// Re-tax every line: RCM on -> collect zero; RCM off -> restore the amount from the stored rate.
def invItems = ec.entity.find("mantle.account.invoice.InvoiceItem").condition("invoiceId", invoiceId).list()
for (def it : invItems) {
    def taxable = (it.taxableAmount ?: ((it.quantity?:1)*(it.amount?:0))) as BigDecimal
    def cA = new BigDecimal(0), sA = new BigDecimal(0), iA = new BigDecimal(0)
    if (rcm != 'Y') {
        cA = taxable.multiply((it.cgstRate ?: 0.0) as BigDecimal).divide(new BigDecimal(100), 2, java.math.RoundingMode.HALF_UP)
        sA = taxable.multiply((it.sgstRate ?: 0.0) as BigDecimal).divide(new BigDecimal(100), 2, java.math.RoundingMode.HALF_UP)
        iA = taxable.multiply((it.igstRate ?: 0.0) as BigDecimal).divide(new BigDecimal(100), 2, java.math.RoundingMode.HALF_UP)
    }
    ec.service.sync().name("update#mantle.account.invoice.InvoiceItem").parameters([
        invoiceId:invoiceId, invoiceItemSeqId:it.invoiceItemSeqId,
        cgstAmount:cA, sgstAmount:sA, igstAmount:iA]).call()
}
ec.service.sync().name("mantle.account.InvoiceServices.update#InvoiceTotals").parameters([invoiceId:invoiceId]).call()
def items2 = ec.entity.find("mantle.account.invoice.InvoiceItem").condition("invoiceId", invoiceId).list()
def tCgst = 0.0, tSgst = 0.0, tIgst = 0.0, tTaxable = 0.0
for (def it : items2) {
    tCgst += (it.cgstAmount ?: 0.0); tSgst += (it.sgstAmount ?: 0.0); tIgst += (it.igstAmount ?: 0.0)
    tTaxable += (it.taxableAmount ?: ((it.quantity?:1)*(it.amount?:0)))
}
ec.service.sync().name("update#mantle.account.invoice.Invoice").parameters([
    invoiceId:invoiceId, invoiceTotal:tTaxable, unpaidTotal:tTaxable, totalCgst:tCgst, totalSgst:tSgst, totalIgst:tIgst, totalTaxableAmount:tTaxable]).call()

            ec.service.sync().name("mantle.account.InvoiceServices.update#InvoiceTotals").parameters([invoiceId:invoiceId]).call()

            // Re-aggregate GST values
            def invItems = ec.entity.find("mantle.account.invoice.InvoiceItem").condition("invoiceId", invoiceId).list()
            def tCgst = 0.0, tSgst = 0.0, tIgst = 0.0, tTaxable = 0.0
            for (def it : invItems) {
                tCgst += (it.cgstAmount ?: 0.0)
                tSgst += (it.sgstAmount ?: 0.0)
                tIgst += (it.igstAmount ?: 0.0)
                tTaxable += (it.taxableAmount ?: ((it.quantity?:1)*(it.amount?:0)))
            }
            ec.service.sync().name("update#mantle.account.invoice.Invoice").parameters([
                invoiceId: invoiceId,
                totalCgst: tCgst, totalSgst: tSgst, totalIgst: tIgst, totalTaxableAmount: tTaxable
            ]).call()

def item = ec.entity.find("mantle.account.invoice.InvoiceItem")
            .condition("invoiceId", invoiceId).condition("invoiceItemSeqId", invoiceItemSeqId).one()
if (item == null) { ec.message.addError("Line item not found."); return }
// ZE-SALES-001 (SL-032/SL-046): reject non-numeric input before parsing (avoids NumberFormatException).
def _numOk = { v -> !v || v.toString().trim() == '' || (v.toString().trim() ==~ /-?\d*\.?\d+/) }
if (!_numOk(quantity) || !_numOk(amount) || !_numOk(discountPercent)) {
    ec.message.addError("Quantity, Unit Price and Discount must be numbers (letters aren't allowed).")
    return
}
def qty = new BigDecimal(quantity ?: 0)
def price = new BigDecimal(amount ?: 0)
if (qty.signum() <= 0) { ec.message.addError("Quantity must be greater than zero."); return }
if (price.signum() < 0) { ec.message.addError("Unit price cannot be negative."); return }
// ZE-SALES-020 (SL-042): keep the line discount when qty/price is edited (posted value if the
// edit form changed it, else the stored one); GST stays on the discounted value.
def discPct = new BigDecimal(discountPercent ?: (item.discountPercent ?: 0))
def gross = qty.multiply(price)
def discAmt = gross.multiply(discPct).divide(new BigDecimal(100), 2, java.math.RoundingMode.HALF_UP)
def taxableVal = gross.subtract(discAmt)
def cgstRate = (item.cgstRate ?: 0.0) as BigDecimal
def sgstRate = (item.sgstRate ?: 0.0) as BigDecimal
def igstRate = (item.igstRate ?: 0.0) as BigDecimal
def cgstAmount = taxableVal.multiply(cgstRate).divide(new BigDecimal(100), 2, java.math.RoundingMode.HALF_UP)
def sgstAmount = taxableVal.multiply(sgstRate).divide(new BigDecimal(100), 2, java.math.RoundingMode.HALF_UP)
def igstAmount = taxableVal.multiply(igstRate).divide(new BigDecimal(100), 2, java.math.RoundingMode.HALF_UP)
if (curInv.isReverseCharge == 'Y') { cgstAmount = 0.0; sgstAmount = 0.0; igstAmount = 0.0 }
ec.service.sync().name("update#mantle.account.invoice.InvoiceItem").parameters([
    invoiceId:invoiceId, invoiceItemSeqId:invoiceItemSeqId,
    quantity:qty, amount:price, taxableAmount:taxableVal,
    discountPercent:discPct, discountAmount:discAmt,
    cgstAmount:cgstAmount, sgstAmount:sgstAmount, igstAmount:igstAmount]).call()
ec.service.sync().name("mantle.account.InvoiceServices.update#InvoiceTotals").parameters([invoiceId:invoiceId]).call()
def invItems = ec.entity.find("mantle.account.invoice.InvoiceItem").condition("invoiceId", invoiceId).list()
def tCgst = 0.0, tSgst = 0.0, tIgst = 0.0, tTaxable = 0.0
for (def it : invItems) {
    tCgst += (it.cgstAmount ?: 0.0); tSgst += (it.sgstAmount ?: 0.0); tIgst += (it.igstAmount ?: 0.0)
    tTaxable += (it.taxableAmount ?: ((it.quantity?:1)*(it.amount?:0)))
}
ec.service.sync().name("update#mantle.account.invoice.Invoice").parameters([
    invoiceId:invoiceId, invoiceTotal:tTaxable, unpaidTotal:tTaxable, totalCgst:tCgst, totalSgst:tSgst, totalIgst:tIgst, totalTaxableAmount:tTaxable]).call()

def _st2 = { s -> (s && s.toString().trim().length() >= 2 && (s.toString().trim().substring(0,2) ==~ /[0-9]{2}/)) ? s.toString().trim().substring(0,2) : null }
def _c2 = { s -> (s && s.toString().trim() ==~ /[0-9]{2}/) ? s.toString().trim() : null }
def _bReg2 = invoice?.toPartyId ? ec.service.sync().name("zenith.tax.TaxServices.get#PartyTaxRegistration").parameters([partyId:invoice.toPartyId]).call() : null
def _sReg2 = invoice?.fromPartyId ? ec.service.sync().name("zenith.tax.TaxServices.get#PartyTaxRegistration").parameters([partyId:invoice.fromPartyId]).call() : null
def _buyerState = _st2(invoice?.buyerGstin) ?: _c2(invoice?.placeOfSupplyStateCode) ?: _c2(_bReg2?.regionGeoId) ?: _st2(_bReg2?.registrationNumber)
def _sellerState = _st2(invoice?.supplierGstin) ?: _c2(invoice?.supplierStateCode) ?: _c2(_sReg2?.regionGeoId) ?: _st2(_sReg2?.registrationNumber)
// Only for a normal (non-RCM, non-export) sale to a stateless buyer — those regimes have their own rules.
buyerStateMissing = (invoice != null && !_buyerState && invoice.isReverseCharge != 'Y' && invoice.isExport != 'Y')
def _sName = _sellerState ? ec.entity.find("zenith.erp.india.IndiaState").condition("stateCode", _sellerState).one()?.stateName : null
fallbackStateLabel = _sellerState ? (_sellerState + (_sName ? ' - ' + _sName : '')) : 'your registered state'

posTxn = ec.entity.find("zenith.erp.pos.PosTransaction")
    .condition("linkedInvoiceId", invoiceId).list().find { true }
posPayList = []
posSaleStarted = null; posSaleClosed = null; posPayMethods = ''
if (posTxn) {
    posSaleStarted = posTxn.entryDate
    posSaleClosed = posTxn.completedDate
    posPayList = ec.entity.find("zenith.erp.pos.PosPayment")
        .condition("transactionId", posTxn.transactionId).orderBy("paymentDate").list()
    if (posPayList) {
        posPayMethods = posPayList.collect { it.paymentMethod ?: 'Other' }.unique().join(', ')
        if (!posSaleClosed) { def pd = posPayList.collect { it.paymentDate }.findAll { it }; if (pd) posSaleClosed = pd.max() }
    } else if (posTxn.isCredit == 'Y') { posPayMethods = 'Credit (unpaid)' }
    if (!posSaleClosed) posSaleClosed = posTxn.lastUpdatedStamp
}
